"""Add original file-ingestion and outbound-email Web Development tracks."""
import copy
import datetime
import html
import json
import re
import subprocess
import uuid
from pathlib import Path

root = Path(__file__).resolve().parents[1]
fixture = root / 'src/data/fixtures.json'
entries = json.loads(fixture.read_text())
by_path = {entry['path']: entry for entry in entries}
stamp = datetime.datetime.now(datetime.UTC).isoformat()

def p(value):
    return '<p>' + html.escape(value) + '</p>'

def link(path):
    title = by_path[path]['title'] if path in by_path else next((item['title'] for item in lessons if item['path'] == path), None)
    assert title is not None, path
    return '<a href="/' + html.escape(path, quote=True) + '">' + html.escape(title) + '</a>'

hubs = [
    dict(path='web-tech/file-ingestion-and-private-asset-lifecycle', title='File Ingestion and Private Asset Lifecycle', summary='Accept files through bounded sessions, verify bytes before release, and recheck access at download.', overview='A file moves through several authorities: browser selection, transfer, temporary storage, inspection, processing, and eventual download. None of those steps alone proves that the file is safe or that the current requester may see it. This track follows evidence files uploaded to a case-review application. It separates a transfer that finished from an asset that has been accepted, and treats every derived preview and export as a new protected object. The examples use small deterministic values to expose state transitions; a real storage service needs its own signed-request and checksum rules.', bridges=['web-tech/safe-file-upload-pipeline','web-tech/multipart-upload-progress-and-retry-boundaries']),
    dict(path='web-tech/outbound-email-and-delivery-state', title='Outbound Email and Delivery State', summary='Queue purpose-limited messages, handle provider feedback, and keep account links short-lived.', overview='Sending email crosses an application queue, a mail provider, and a recipient mailbox. A provider accepting a request is not proof that the person read the message. This track follows case-review notices and account links from event creation through template rendering, sender identity, bounce handling, and suppression. It keeps marketing preference separate from security or transactional purpose, while recognizing that every sender must respect provider and recipient rules. Application state should record intent and observed delivery events without copying private case data into transport logs.', bridges=['web-tech/background-jobs-and-outbox','web-tech/web-push-and-notification-delivery']),
]

lessons = [
    dict(hub=0, path='web-tech/upload-intake-budgets-and-storage-ownership', title='Upload Intake Budgets and Storage Ownership', summary='Bound each upload before receiving bytes and keep untrusted objects outside public serving paths.',
    definition='An upload intake contract specifies who may start a transfer, which case it belongs to, which types and sizes are accepted, and where bytes live before review. A browser file picker and Content-Type header are hints, not server validation. The application must enforce total request size, per-file size, file count, transfer duration, and concurrent-session limits before unbounded memory or disk allocation. Storage ownership matters: an untrusted file must not be placed under a public web directory or given a user-supplied executable name. A successful transfer creates a pending asset record, not a trusted document.',
    case='Reviewer 29 attaches evidence to case 47. The permitted class is an image or PDF up to 23 MiB, with four attachments per case and two concurrent transfers per reviewer. The browser selects a file named final-report.pdf, but the server generates asset 62 and an opaque object key. It checks reviewer 29 may edit case 47 before issuing any transfer permission. The request advertises 12 MiB; the server still counts actual received bytes and stops at the cap. Temporary bytes land in a private pending area. The case detail page shows Processing rather than a download link until inspection finishes.',
    implementation='Apply the earliest practical body limit at the edge or server and another limit in the streaming receiver. Count actual bytes, not a declared length alone. Enforce actor, case, tenant, rate, and concurrency controls before signing direct-to-storage requests or accepting multipart bodies. Restrict the storage key and allowed method; never let the browser choose a bucket path that maps directly to another tenant. Persist one pending asset ID with owner, expected size range, purpose, creation time, and expiry. If direct transfer is used, inspect the resulting object size and identity server-side before moving the record forward. Reject filenames with dangerous handling in display or logging, and store the original name only as untrusted metadata.',
    cost='Receiving n bytes costs O(n) transfer and storage, but buffering the whole request adds O(n) process memory that a streaming receiver can avoid. Parallel uploads multiply disk and network load by active sessions; a per-file cap alone does not protect capacity. A staging object and metadata record cost extra writes and need expiry cleanup. Put quotas at the user, tenant, and service levels so one busy tenant cannot consume all room. Measure rejected bytes, active sessions, incomplete staging age, object storage growth, and the delay between transfer completion and inspection.',
    failure='The UI rejects a large file locally, but a scripted client posts a larger body directly and the server buffers it before checking length. Several requests exhaust memory. Enforce limits as bytes arrive and cap concurrent sessions. Another path writes uploaded filenames into a public directory. A crafted name collides with an existing asset or reaches an executable route. Use opaque storage keys and keep staging outside public serving. Test missing length, false length, slow transfer, many tiny parts, parallel uploads, expired permission, tenant switch, and a transfer that ends exactly at the configured boundary.',
    drill='For case 47, request a transfer as reviewer 29 and confirm the server creates asset 62 in pending state. Try the same call as reviewer 62 without case rights. Stream bytes just below, at, and above 23 MiB without preloading them all in the handler. Reuse a transfer grant for a different object key and confirm rejection. Start more than two simultaneous transfers, abandon one, and verify expiry removes its pending object and releases capacity. Check that no pending byte path is reachable from a public URL.',
    decision='Authorize and bound the transfer before accepting bytes, then retain the object privately until it passes later checks.',
    code='function withinUploadBudget(receivedBytes, limitBytes, activeCount, maxActive) {\n  return receivedBytes <= limitBytes && activeCount < maxActive;\n}\nconsole.log(withinUploadBudget(24 * 1024 * 1024, 23 * 1024 * 1024, 1, 2));\n// Output: false',
    checks=['Declared size never replaces actual byte counting.','Staged objects are private and use server-owned keys.','Actor, tenant, concurrency, and expiry rules hold before transfer.'], mistakes=['Checking size only in the browser.','Treating the filename as a safe storage key.','Calling a transferred object ready for download.'], related=['web-tech/safe-file-upload-pipeline','web-tech/object-level-authorization-for-reads-and-writes','web-tech/retention-inventory-and-expiry-workflows']),
    dict(hub=0, path='web-tech/resumable-transfer-parts-and-integrity', title='Resumable Transfer Parts and Integrity', summary='Track part ownership and verify the completed object rather than trusting a progress bar.',
    definition='A resumable upload divides one object into parts and records which bytes or numbered parts the storage service has accepted. It reduces retransmission after a network break, but completion is a separate server decision. Client-reported progress measures sent bytes, not durable, inspected, or usable bytes. Each part belongs to one upload session, object key, owner, and expiry. The final object must be assembled under the storage service’s rules and checked for expected length and a supported checksum before it is attached to a case. Part identifiers and provider tags are protocol data; a final multipart tag should not be assumed to be a whole-file digest.',
    case='Reviewer 29 uploads a 47 MiB video for case 47 in five parts. The fourth part times out after storage may already have accepted it. The client asks the server for current part state and retries only if the authoritative record still needs it. The server keeps upload 62 scoped to reviewer 29 and case 47. A second tab cannot finish upload 62 with a different file. After all five parts are listed, the server completes the object and checks size and the chosen full-object checksum. It then marks the transfer complete, while content inspection remains pending.',
    implementation='Choose part size and maximum count according to the selected storage service, not an assumed universal constant. Bind initiation, part authorization, completion, and abort to the same application asset. Require the client to present an upload session ID, but look up owner and object key on the server. Use storage-reported part identifiers and checksums where supported; do not accept a forged client list as proof. Recheck object metadata after completion and compare an application-level digest if the product requires end-to-end integrity. Record retryable and permanent failures separately. Expire abandoned sessions and abort incomplete multipart storage to prevent orphaned-part cost. Progress UI should distinguish sending, assembling, verifying, and processing.',
    cost='For n bytes and part size s, transfer uses about n divided by s parts plus initiation and completion calls. Smaller parts reduce retransmitted bytes but increase requests and metadata; excessive parallelism competes for client bandwidth and server limits. Checksum computation touches O(n) bytes and can be streamed with bounded memory. Retained incomplete parts consume storage until completion or abort, so lifecycle cleanup is a cost control as well as housekeeping. Track orphaned session age, part retry rate, checksum mismatch, completion failures, and time from 100 percent sent to usable asset.',
    failure='The progress bar reaches 100 percent and the UI exposes a download link, but final assembly failed. A reviewer sees a missing or truncated video. Gate access on verified completion plus inspection, not browser progress. Another system retries a timed-out part by creating a second upload session and loses the original accepted parts. Reconcile against the original session first. Test duplicate part number, wrong order, stale upload ID, part from another user, completion timeout, mismatched digest, abort during active requests, and cleanup of an abandoned multipart session.',
    drill='Begin upload 62 and record five planned parts with their expected byte ranges. Force a timeout on part four after the storage write, query authoritative state, and finish without uploading parts one through three again. Submit a part list with a missing item and reject completion. Corrupt one local part and verify the full-object check fails. Cancel the upload, then confirm no public asset appears and the cleanup job releases incomplete storage after its defined grace period.',
    decision='Separate sent-byte progress from verified object completion, and make retries reconcile one owned session.',
    code='function completedPartBytes(parts) {\n  return parts.reduce((bytes, part) => bytes + (part.accepted ? part.size : 0), 0);\n}\nconsole.log(completedPartBytes([{ size: 8, accepted: true }, { size: 8, accepted: false }]));\n// Output: 8',
    checks=['All accepted parts belong to one authorized session.','Full-object length and integrity are checked after assembly.','Abandoned multipart sessions are eventually aborted.'], mistakes=['Equating browser progress with durable completion.','Treating a multipart tag as a whole-file digest.','Starting a fresh session after every uncertain part response.'], related=['web-tech/multipart-upload-progress-and-retry-boundaries','web-tech/upload-intake-budgets-and-storage-ownership','web-tech/large-export-download-and-integrity']),
    dict(hub=0, path='web-tech/file-quarantine-inspection-and-derived-previews', title='File Quarantine, Inspection, and Derived Previews', summary='Keep raw uploads private until type checks, scanning, and bounded processing finish.',
    definition='File inspection is the transition from transferred bytes to an asset that the application is willing to handle. A filename extension, browser MIME type, or first-byte signature alone cannot prove that a file is benign or that a parser can process it safely. The server should validate an allowlisted format with a maintained parser, apply resource limits, scan according to product risk, and create derived previews in an isolated worker. The raw upload remains quarantined while that work is pending or failed. A derived thumbnail is a separate object with its own access and retention rules; it must not be published merely because the original upload was accepted.',
    case='Asset 62 claims to be a PDF for case 47. Its first bytes resemble a PDF, but the inspection worker discovers an embedded payload that violates the product’s accepted profile. The worker records rejected with a reason code that can be shown without exposing scanner internals. The file is never linked from case details. A valid image in asset 63 passes format checks and scanning, then a processor writes a small preview with dimensions and checksum. Both original and preview remain tenant-scoped. If preview generation fails, the original can stay pending or available without preview according to an explicit product rule.',
    implementation='Keep a state machine such as pending, inspecting, accepted, rejected, and processing-failed. Allow only named transitions guarded by asset version so duplicate jobs cannot reverse a final decision. Validate the entire file, not only an extension or a few header bytes. Run parsers and thumbnail builders with CPU, memory, time, output-size, and file-count limits; archives can expand far beyond their compressed size. Keep untrusted files out of application execution paths and avoid sending private evidence to an external scanning service without an approved data contract. Store derived assets under generated keys, record their source version, and require authorization at retrieval.',
    cost='Inspection is at least O(n) byte work for n-byte input and may include expensive decoding; thumbnails add CPU and output storage. Deep archive scanning can expand work beyond compressed input, so set a decompressed-byte and entry-count budget. Queueing inspection protects request latency but adds a delay before use. Retaining rejected raw bytes creates risk and cost; set a reviewed retention rule for audit and cleanup. Measure pending age, parser timeouts, rejection reasons, worker crashes, preview mismatch, and accepted-to-visible delay. A faster path must not silently bypass checks under load.',
    failure='A parser worker crashes after marking the asset accepted but before writing the preview, and a retry uses stale state to publish an old thumbnail. Make output idempotent by source version and commit the availability transition only after required artifacts exist. Another processor decompresses an archive without a cap and exhausts memory. Enforce byte and entry budgets in the worker. Test mislabeled types, polyglot files, malformed images, archive expansion, duplicate queue delivery, scanner outage, worker timeout, and a tenant permission change while inspection runs.',
    drill='Upload three files for case 47: a valid image, a mislabeled script, and a compressed file that exceeds the expansion budget. Verify each moves through the expected states and only the valid one receives a derived preview. Retry the worker after a deliberate crash and confirm no duplicate public record or stale output appears. Remove reviewer 29’s case permission during processing, then attempt to read both raw and preview objects. Confirm authorization is checked at retrieval, independent of the earlier upload right.',
    decision='Release files only after a bounded inspection transition, and bind every derivative to the inspected source version.',
    code='function mayExposeAsset(asset) {\n  return asset.inspection === "accepted" && asset.requiredOutputsReady;\n}\nconsole.log(mayExposeAsset({ inspection: "pending", requiredOutputsReady: true }));\n// Output: false',
    checks=['Uninspected and rejected bytes have no public retrieval path.','Workers are bounded against malformed and expanded content.','Derived previews match the inspected source version and access scope.'], mistakes=['Using an extension or MIME header as complete validation.','Running parsers without resource limits.','Serving a thumbnail through a weaker authorization path.'], related=['web-tech/safe-file-upload-pipeline','web-tech/background-jobs-and-outbox','web-tech/object-level-authorization-for-reads-and-writes']),
    dict(hub=0, path='web-tech/private-asset-download-revocation-and-expiry', title='Private Asset Downloads, Revocation, and Expiry', summary='Authorize every original and derivative read, then expire grants and storage on policy.',
    definition='A stored file is not a public URL by default. Download access depends on the current actor, case, tenant, asset state, and sometimes a purpose or time window. A signed storage URL can carry a short-lived capability after authorization, but it cannot revoke bytes already downloaded and may outlive an immediate permission change until expiry. A proxy route offers tighter per-request control at the cost of application bandwidth. Either model needs content-disposition and type handling that prevents active content from executing under the application origin. Originals, thumbnails, transcripts, and exports need the same ownership rule.',
    case='Reviewer 29 may read asset 63 while assigned to case 47. The app issues a brief download grant for the accepted image and an equally scoped preview. When reviewer 29 loses case access, new grants are denied. An earlier short grant remains usable only for its bounded lifetime under the selected policy. Reviewer 62 cannot use asset 63’s predictable ID to get either object. When case 47 reaches its retention deadline, a deletion workflow removes raw, preview, and stale staging objects, records completion, and prevents a backup restore from making the file visible again.',
    implementation='Map asset IDs to private object keys on the server and check current object-level authorization before proxying or signing. Bind the grant to one object, operation, and short expiry; do not sign arbitrary browser-supplied keys. Use response headers appropriate to the actual detected type, and use attachment disposition for content that should not render in the app origin. Avoid revealing private object names through cache keys or analytics. For revocation, document the maximum grant lifetime and consider proxying higher-risk objects. Maintain an inventory of derivatives and processing outputs so expiry and erasure can remove all related bytes. Test cache behavior under account and tenant switching.',
    cost='A proxy download uses O(n) application egress for n bytes and keeps the app in the transfer path. Direct signed storage can reduce that load but has a revocation delay bounded by grant lifetime and storage controls. Checking authorization is near O(1) with indexed asset and case relations, while deletion must visit O(k) related objects. Caches can save repeated transfer but become a disclosure risk if keys omit tenant or permission context. Measure denied reads, expired grant use, object leaks after deletion, orphaned derivatives, and download error rates after revocation.',
    failure='A preview URL uses a public bucket while the original file uses a protected route. Reviewer 62 sees a sensitive thumbnail by guessing asset 63. Give every derivative the same ownership check. Another app serves user-controlled HTML inline on its own origin; a downloaded file executes with application context. Force safe type and disposition policy. Test a removed case assignment, shared browser history, stale service-worker cache, expired signed grant, cross-tenant ID, asset deleted during transfer, and a restored backup that contains an old object key.',
    drill='Grant reviewer 29 read access to asset 63 and deny reviewer 62. Produce one original and one preview, then inspect both retrieval routes and cache headers. Revoke reviewer 29’s case assignment and prove new grants fail; record the bounded behavior of an already issued grant. Run retention deletion and enumerate all keys tied to the asset, including staging and derivatives. Restore an older copy of metadata in a test and verify a deletion marker prevents the asset from reappearing.',
    decision='Authorize every retrieval from current case state and make grant expiry and derivative deletion explicit.',
    code='function mayIssueDownload(actorCases, asset) {\n  return asset.state === "accepted" && actorCases.has(asset.caseId);\n}\nconsole.log(mayIssueDownload(new Set([62]), { caseId: 47, state: "accepted" }));\n// Output: false',
    checks=['Originals and derivatives share current object-level authorization.','Signed grants are scoped and expire within the documented bound.','Retention cleanup includes staging and all derived objects.'], mistakes=['Publishing a preview while protecting only the original.','Using long-lived signed URLs as instant revocation.','Deleting metadata while leaving object copies behind.'], related=['web-tech/object-level-authorization-for-reads-and-writes','web-tech/retention-inventory-and-expiry-workflows','web-tech/large-export-download-and-integrity']),
]

lessons.extend([
    dict(hub=1, path='web-tech/email-intent-outbox-and-idempotent-send', title='Email Intent, Outbox, and Idempotent Send', summary='Record one message intent with the business event and handle uncertain provider responses.',
    definition='An outbound email is a side effect of a business event, not the business event itself. A database transaction should record the case assignment or account action and a message intent together, then a worker sends the message through a provider. This outbox boundary prevents a committed change from losing its notice when the process crashes. It also prevents a failed mail request from rolling back a legitimate case action. Delivery is not exactly once: a worker can time out after the provider accepts a message, and retries can produce duplicates unless the application uses stable intent IDs and the provider’s idempotency contract where available.',
    case='Reviewer 29 is assigned case 47. The assignment transaction writes the new owner and one email intent keyed by assignment revision 6. A worker reads that intent, checks the current recipient and purpose policy, renders the message, and asks the provider to send. The provider response times out. The worker does not create a new intent on retry; it consults the stored attempt and provider state if possible, then retries with the same key under its integration rules. A duplicate queue delivery cannot create two independent notice records. The case assignment remains valid whether mail is delayed or rejected.',
    implementation='Persist an intent ID, business event ID, recipient account, template key and version, purpose, locale, expiry, and status in the same transaction as the business change. Do not put a full private case note into the queue payload. A worker claims a bounded batch with lease or comparable ownership, rechecks recipient eligibility at send time, and records provider message ID and attempt outcome. Distinguish transient errors, permanent rejection, and uncertain acceptance. Use provider idempotency when supported; otherwise document the duplicate risk and make recipient-facing content tolerant of repetition. Give stale security links a short expiry instead of retrying them indefinitely. Treat retries as bounded work with backoff and a dead-letter review path.',
    cost='Writing one intent is O(1) database work; rendering and sending cost a provider call and queue capacity. Leases and retries add state but protect against process failure. An assignment wave can generate many intents, so batch worker capacity and provider rate limits must be measured. A long queue delay can make a message misleading if case ownership changes; either recheck current state or word the notice as a historical event. Track intent age, provider acceptance uncertainty, duplicate sends, permanent rejection, and user-visible latency. Queue storage grows with event rate times retention until terminal status and cleanup.',
    failure='The application sends email before committing the assignment. The provider accepts it, then the database transaction fails; reviewer 29 receives a notice for a case never assigned. Commit the business event with an intent first. Another worker treats timeout as definite failure and sends a second message with a new key, creating duplicates. Keep one intent and reconcile uncertain attempts. Test crash before commit, crash after commit but before queue wakeup, provider timeout after acceptance, duplicate worker claim, revoked recipient access, expired link, and a message that remains queued longer than its usefulness.',
    drill='Assign case 47 to reviewer 29 and inspect the same database transaction for assignment revision 6 and one email intent. Kill the worker before sending and restart it; the notice should still be considered. Force a provider timeout after remote acceptance and exercise the chosen reconciliation rule. Deliver the queue item twice and inspect intent and provider IDs. Change the case owner while the message is queued, then verify the send-time policy produces the documented outcome without leaking private case content.',
    decision='Commit message intent with the business change, then send through a retryable worker using one stable identity.',
    code='function intentKey(caseId, assignmentRevision) {\n  return `case:${caseId}:assignment:${assignmentRevision}`;\n}\nconsole.log(intentKey(47, 6));\n// Output: case:47:assignment:6',
    checks=['A committed business event has one durable message intent.','Duplicate queue work does not create a new intent.','Uncertain provider acceptance is reconciled before unsafe retry.'], mistakes=['Sending before the business transaction commits.','Treating a timeout as proof the provider did not accept mail.','Putting private case notes into queue payloads.'], related=['web-tech/background-jobs-and-outbox','web-tech/idempotent-write-requests','web-tech/notification-opt-in-and-channel-preference']),
    dict(hub=1, path='web-tech/email-template-data-and-account-link-boundaries', title='Email Template Data and Account Link Boundaries', summary='Render limited message data and keep action links short-lived, single-purpose, and server-verified.',
    definition='An email template is a public-facing rendering boundary that can leak data through subject lines, previews, tracking, forwarding, or mailbox compromise. A message should carry only the information needed for its purpose and defer private case details to an authenticated application route. Account-action links need unpredictable tokens, one purpose, expiration, and server verification before changing state. A click is not a completed account action: link scanners and mail clients may prefetch URLs, so state-changing actions should require an explicit user step after a safe landing page. A template version belongs to the send record so later edits do not erase what was actually mailed.',
    case='Reviewer 29 receives a case assignment notice. The subject says New assignment, with no client name or private diagnosis. The message links to a generic case route; the app authenticates reviewer 29 and checks current permission before showing case 47. A separate account recovery email has a short-lived token bound to recovery purpose and account, stored server-side as a verifier rather than raw reusable text where feasible. A mail-security scanner opens the recovery link first. It sees an inert landing page and cannot reset the password. Reviewer 29 must deliberately submit the final action within the token lifetime.',
    implementation='Define allowed fields per template, escape untrusted values for both HTML and text alternatives, and avoid raw URLs or tokens in logs and analytics. Generate absolute application links from a trusted configured origin, not request Host headers. Bind recovery or verification tokens to account, action, issued time, expiry, and replay state, and compare them safely on the server. Use a GET landing page that performs no mutation, then a CSRF-aware explicit POST or equivalent step. Rate-limit requests for account links without disclosing whether an address exists. Recheck current account state, tenant membership, and authorization when the action is submitted. Keep a retained template revision and locale choice for troubleshooting.',
    cost='Template rendering is O(m) in message length, usually small; generating and verifying a token adds bounded cryptographic work and a short-lived record. Text and HTML versions add editorial review but reduce mail-client failure. A low-detail subject may require the user to sign in for context, which is an intentional privacy tradeoff. Link tokens add cleanup and replay state. Measure failed template renders, invalid or expired token attempts, link-scanner visits, completed actions after landing, and whether private fields appear in message snapshots or telemetry. Do not optimize clicks by putting confidential case content into inbox previews.',
    failure='The recovery URL performs a password reset on GET. A mail scanner fetches it before the user sees the message, consuming the token or changing account state. Make the GET read-only and require explicit confirmation. Another template interpolates a case title that contains HTML into the message body without escaping; the result changes rendering or creates a malicious link. Escape values and use an allowlist. Test forwarded mail, stale tenant assignment, changed account address, expired token, replayed token, scanner prefetch, HTML-disabled client, and a request with a hostile Host header.',
    drill='Render assignment notice revision 6 with a private case title and inspect subject, preview, text, and HTML for leakage. Open the link signed out and then as reviewer 62; the case route must reauthorize. Issue a recovery token, fetch its landing URL twice, and prove neither GET changes account state. Submit the final action once, replay it, and confirm the second attempt fails. Test expiration and an account change between token issue and use. Compare the stored template revision to the message that was sent.',
    decision='Keep email content narrow and make account links server-verified actions rather than self-executing URLs.',
    code='function actionTokenUsable(token, purpose, now) {\n  return token.purpose === purpose && !token.used && now < token.expiresAt;\n}\nconsole.log(actionTokenUsable({ purpose: "recover", used: true, expiresAt: 80 }, "recover", 47));\n// Output: false',
    checks=['Private case details require current in-app authorization.','GET link visits do not perform account mutations.','Purpose, expiry, and replay checks precede token use.'], mistakes=['Putting secrets or private details in a subject line.','Building links from an untrusted request origin.','Letting a link scanner consume a state-changing token.'], related=['web-tech/account-recovery-and-session-revocation','web-tech/object-level-authorization-for-reads-and-writes','web-tech/message-catalog-contracts-and-fallback']),
    dict(hub=1, path='web-tech/email-provider-events-bounces-and-suppression', title='Email Provider Events, Bounces, and Suppression', summary='Reconcile accepted, delivered, bounced, and complained-about messages without unsafe repeated sends.',
    definition='A mail provider accepting an API request records an attempt, not guaranteed inbox delivery. Later events may report delivery, delay, rejection, bounce, or complaint, and they can arrive more than once or out of order. The application must map provider message IDs back to its own intent and recipient, validate event authenticity under the chosen provider contract, and update state monotonically. A hard failure or complaint may suppress further optional mail to that address. Temporary failures require a bounded retry policy, while a security-critical notice may need another approved channel if email cannot arrive. Suppression policy depends on message purpose; promotional and transactional notices should not be collapsed into one toggle.',
    case='Case notice intent 62 was accepted by a provider but later reports a permanent bounce for reviewer 29’s address. The event handler verifies the callback, finds the matching provider ID, marks the attempt bounced, and records a suppression reason for the address under the appropriate category. A duplicate bounce event does not change counts twice. A delayed delivered event for an older attempt cannot erase the newer bounce. The case assignment itself remains. The app can show a neutral in-product notice asking reviewer 29 to update contact information rather than repeatedly sending to an unusable mailbox.',
    implementation='Store the application intent ID and provider message ID mapping per recipient; multi-recipient sends complicate feedback attribution, so choose batching carefully. Validate signed provider callbacks and event IDs, then deduplicate before applying transitions. Separate accepted, delayed, delivered, bounced, complained, and unknown states with timestamps and provider references. Classify permanent and transient failures according to current provider definitions, not a string fragment. Maintain suppression at the appropriate account or tenant scope, and check it before every optional send. Define how account-security messages behave when an address is suppressed, including safe alternate routes. Reconcile missing feedback on a schedule without claiming silence means delivery.',
    cost='An event callback uses indexed message lookup and O(1) state update in the common case. Each attempt and feedback item adds small storage, while repeated transient retries can grow provider cost and reputation risk. A suppression lookup per send is cheap with an index; stale suppression data can keep sending to invalid addresses. Collect aggregate bounce, complaint, delay, and provider rejection rates without logging full addresses or message bodies. Monitor feedback lag, unknown provider IDs, duplicate events, suppression effectiveness, and critical notices with no working channel.',
    failure='The app treats API accepted as delivered and tells a user the recipient read the notice. A later bounce arrives, but the UI has no state for it. Keep accepted distinct from delivered and never infer human reading from delivery. Another worker retries a permanent bounce indefinitely, harming sender reputation and flooding logs. Suppress or stop according to policy. Test forged callback, duplicate event, delayed earlier event, missing provider ID, changed recipient address, provider outage, temporary rejection, and a complaint that must halt optional messages without hiding a required account notice.',
    drill='Send one notice for reviewer 29 and persist its provider ID. Deliver accepted, delayed, bounce, and duplicate bounce events in a test runner. Verify a valid signature is required and a stale delivered event cannot override the bounce. Attempt another optional notice and confirm suppression blocks it. Change the address through an authenticated account flow, then verify the new address has its own confirmation and send policy. Measure unresolved attempts and check that the dashboard does not label provider acceptance as mailbox reading.',
    decision='Treat provider feedback as asynchronous evidence, deduplicate it, and enforce purpose-aware suppression before new sends.',
    code='function maySendNotice(suppression, purpose) {\n  return !suppression.has(purpose);\n}\nconsole.log(maySendNotice(new Set(["optional"]), "optional"));\n// Output: false',
    checks=['Provider acceptance and recipient delivery have distinct states.','Duplicate feedback cannot overwrite a later terminal event.','Suppression is checked by purpose before sending.'], mistakes=['Equating provider acceptance with user reading.','Retrying permanent bounces as transient failures.','Applying one preference to every security and optional message.'], related=['web-tech/signed-webhook-delivery-and-replay','web-tech/email-intent-outbox-and-idempotent-send','web-tech/notification-opt-in-and-channel-preference']),
    dict(hub=1, path='web-tech/sender-identity-reputation-and-message-observability', title='Sender Identity, Reputation, and Message Observability', summary='Configure authenticated sending domains and measure delivery without exposing message content.',
    definition='Outbound mail depends on a domain whose sending path is authenticated and whose reputation reflects recipient response. SPF, DKIM, and DMARC serve different roles in authorizing or aligning mail; none alone guarantees inbox placement or prevents every form of spoofing. Sender requirements vary by provider, message class, and volume, so deployment checks must use the current provider contract. Marketing mail also needs a functioning preference and unsubscribe path where applicable. Observability should follow a message from application intent through provider acceptance and later feedback without retaining private bodies, account tokens, or full addresses in broad telemetry.',
    case='The case-review service moves notices from a staging domain to its production sending domain. The deployment owner verifies DNS records and message authentication on received test mail before traffic shifts. The system sends a small cohort, watches bounces and complaints, and keeps a rollback route to the old verified sender if the new path fails. An assignment email and a promotional product digest use different purpose labels and preference checks. The operations dashboard shows intent age, accepted count, delayed count, bounce count, and unknown feedback count by sender domain, but not case titles or recovery links.',
    implementation='Inventory every service allowed to send for the domain, then configure SPF for authorized sending hosts, DKIM signing with managed keys, and a DMARC policy whose alignment and reports can be reviewed. Verify the actual received header result on the chosen recipient providers; a DNS record existing is not enough. Use a stable From identity and approved reply handling. Keep marketing preference and unsubscribe processing separate from transactional or account-security policy, and verify it at send time. Store provider message IDs and coarse status codes for correlation. Remove tokens, bodies, and raw addresses from standard traces, and set retention on detailed delivery records. Alert on sustained rejection or bounce changes with a first action.',
    cost='DNS and key management have low per-message runtime cost but ongoing operational review. DKIM signing adds small cryptographic work, and reports or feedback streams add storage proportional to message volume. A gradual sender migration takes more time but limits reputation damage if configuration is wrong. Rich event logs can help debug delivery while creating privacy exposure, so keep detailed records restricted and expiring. Measure authentication failures, provider rejection, delivery delays, bounces, complaints, unresolved intents, and time to stop optional sends after a preference change. No single rate proves messages reached a person.',
    failure='A new sender domain has a valid-looking DNS record, but the production mail path signs with a different domain. Recipients reject or filter messages. Inspect a received test message and alignment, then pause rollout. Another team logs every HTML body to debug templates, exposing case links and recovery tokens. Keep correlation IDs and safe status instead. Test a missing DKIM key, changed provider, stale DNS during migration, complaint spike, unsubscribe action racing a queued message, feedback stream outage, and rollback to a verified sender without duplicating already accepted intents.',
    drill='Prepare a production sender migration for case notices. Send test mail through the exact planned provider path and inspect authentication results, From identity, and return handling. Compare application intent IDs with provider message IDs and feedback events. Simulate a missing signing configuration and verify rollout halts. Disable optional mail for reviewer 29 while messages remain queued, then confirm the worker checks current preference. Sample logs and traces for raw address, case title, body, and token leakage. Record the rollback decision after a rejection spike.',
    decision='Verify real sender authentication and track message state with minimal, purpose-labeled telemetry.',
    code='function deliveryHealth(sent, rejected) {\n  return sent === 0 ? 0 : rejected / sent;\n}\nconsole.log(deliveryHealth(47, 2).toFixed(3));\n// Output: 0.043',
    checks=['Received test mail passes the intended sender-domain checks.','Optional mail respects the current preference and unsubscribe state.','Delivery telemetry excludes message bodies and action tokens.'], mistakes=['Assuming a DNS record alone proves the sent message aligns.','Using provider accepted count as an inbox success measure.','Logging sensitive message bodies for routine diagnostics.'], related=['web-tech/email-provider-events-bounces-and-suppression','web-tech/telemetry-minimization-and-retention','web-tech/notification-opt-in-and-channel-preference']),
])

